const initialState = {
  dogs: [],
  temperaments: [],
  error: {},
  dogDetail: {},
  currentPage: 1,
  allDogs: [],
  filteredDogs: [],
};

function rootReducer(state = initialState, action) {
  switch (action.type) {
    case "GET_DOGS":
      return {
        ...state,
        dogs: action.payload,
        allDogs: action.payload,
      };
    case "GET_TEMPERAMENTS":
      return {
        ...state,
        temperaments: action.payload,
      };

    case "GET_DETAIL":
      return {
        ...state,
        dogDetail: action.payload,
      };

    case "GET_BY_NAME":
      return {
        ...state,
        dogs: action.payload,
      };

      case 'FILTER_BY':
        const allPokesRevenge = state.allDogs;
        /*  console.log(action.payload); */
        const filter2 =
          action.payload === "Created"
            ? allPokesRevenge.filter((ele) => ele.createdInDb)
            : allPokesRevenge.filter((ele) => !ele.createdInDb);
        return {
          ...state,
          dogs:
            action.payload === "All"
              ? allPokesRevenge
              : filter2.length
              ? filter2
              : [],
        }; 

    case "FILTER_TEMPERAMENT":
      console.log("payload:", action.payload);
      const allDogs = state.allDogs;
      console.log("allDogs:", allDogs);
      const temperamentsFiltered = allDogs.filter((dog) =>
        // dog.temperament &&
        dog.temperaments.map((temp) => temp).includes(action.payload)
      );

      console.log("filteredDogs:", temperamentsFiltered);
      return {
        ...state,
        dogs: temperamentsFiltered,
      };

      case "ORDER_BY":
        if (action.payload === "A-Z") {
          return {
            ...state,
            currentPage: 1,
            filteredDogs: [...state.filteredDogs].sort((prev, next) => {
              if (prev.name > next.name) return 1;
              if (prev.name < next.name) return -1;
              return 0;
            }),
          };
        }
      
        if (action.payload === "Z-A") {
          return {
            ...state,
            currentPage: 1,
            filteredDogs: [...state.filteredDogs].sort((prev, next) => {
              if (prev.name > next.name) return -1;
              if (prev.name < next.name) return 1;
              return 0;
            }),
          };
        }
      
        if (action.payload === "desc") {
          return {
            ...state,
            currentPage: 1,
            filteredDogs: [...state.filteredDogs].sort(
              (prev, next) => prev.weight.slice(0, 2) - next.weight.slice(0, 2)
            ),
          };
        }
      
        if (action.payload === "asc") {
          return {
            ...state,
            currentPage: 1,
            filteredDogs: [...state.filteredDogs].sort(
              (prev, next) => next.weight.slice(0, 2) - prev.weight.slice(0, 2)
            ),
          };
        } 
      
        // use else if instead of else
        else if (action.payload === "reset") {
          return { ...state, filteredDogs: state.allDogs };
        }
      
        // make sure to return the current state if the payload is not recognized
        else {
          return state;
        }
      

    case "LOADING":
      return {
        ...state,
        loading: true,
      };
    case "CLEAN":
      return {
        ...state,
        dogDetail: [],
      };

    default:
      return state;
  }
}
console.log(initialState);

export default rootReducer;
